    Implements a regex matching algorithm that supports:
    - literal characters
    - '.' which matches any single character
    - '*' which matches zero or more of the preceding element
    - '+' which matches one or more of the preceding element

    This is achieved using recursive backtracking to explore all possible patterns.
    """

    def is_match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(text)

        first_match = (i < len(text)) and (pattern[j] == text[i] or pattern[j] == '.')

        if j + 1 < len(pattern) and pattern[j + 1] in '*+':
            if pattern[j + 1] == '*':
                return (is_match(i, j + 2) or 
                        (first_match and is_match(i + 1, j)))
            elif pattern[j + 1] == '+':
                return (first_match and is_match(i + 1, j))

        return first_match and is_match(i + 1, j + 1)

    return is_match(0, 0)

